mapper.sql:
tenant_id = #{tenantId}
AND deleted = b'0'

    AND writer_province LIKE CONCAT('%', #{province}, '%')


    AND writer_city LIKE CONCAT('%', #{city}, '%')


    AND (business_name LIKE CONCAT('%', #{keyword}, '%')
    OR customer_name LIKE CONCAT('%', #{keyword}, '%'))


    AND business_no = #{businessNo}


    AND (current_stage = #{stage} OR business_stage = #{stage})


    AND (manager_name LIKE CONCAT('%', #{manager}, '%')
    OR manager_no = #{manager}
    OR business_writer LIKE CONCAT('%', #{manager}, '%'))


    AND writer_time >= #{beginDate}


    AND writer_time <= CONCAT(#{endDate}, ' 23:59:59')
